import{_ as t,o,c as r,a5 as a}from"./chunks/framework.UjrY2eRK.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"operations/troubleshooting.md","filePath":"operations/troubleshooting.md","lastUpdated":1788123021000}'),i={name:"operations/troubleshooting.md"};function s(n,e,l,c,u,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="health-returns-503" tabindex="-1">Health returns 503 <a class="header-anchor" href="#health-returns-503" aria-label="Permalink to &quot;Health returns 503&quot;">​</a></h2><p>The runtime configuration, storage connection, or schema is unavailable. Check startup logs, required secrets, D1 bindings, SQLite volume permissions, and pending migrations. Health deliberately does not expose the internal failure.</p><h2 id="notification-requests-return-429" tabindex="-1">Notification requests return 429 <a class="header-anchor" href="#notification-requests-return-429" aria-label="Permalink to &quot;Notification requests return 429&quot;">​</a></h2><p>The short source rate limit or the persistent daily delivery budget was exhausted. Confirm the traffic source before raising a limit; do not bypass delivery coordination.</p><h2 id="notification-requests-return-502" tabindex="-1">Notification requests return 502 <a class="header-anchor" href="#notification-requests-return-502" aria-label="Permalink to &quot;Notification requests return 502&quot;">​</a></h2><p>Google OAuth or FCM failed or timed out. Verify outbound HTTPS connectivity, the Firebase service-account scope, project ID, and FCM API status. The response is retryable according to the Matrix push contract.</p><h2 id="notification-requests-return-503" tabindex="-1">Notification requests return 503 <a class="header-anchor" href="#notification-requests-return-503" aria-label="Permalink to &quot;Notification requests return 503&quot;">​</a></h2><p>Configuration, storage, schema validation, or concurrent delivery coordination was unavailable. Check runtime health and storage before retrying.</p><h2 id="self-hosted-source-limits-group-clients-together" tabindex="-1">Self-hosted source limits group clients together <a class="header-anchor" href="#self-hosted-source-limits-group-clients-together" aria-label="Permalink to &quot;Self-hosted source limits group clients together&quot;">​</a></h2><p>The gateway could not establish a trustworthy client address. Configure every direct proxy network in <code>TRINITY_PUSH_GATEWAY_TRUSTED_PROXY_CIDRS</code>, select the header your proxy replaces, and ensure untrusted clients cannot connect directly to the container port.</p><h2 id="sqlite-does-not-start" tabindex="-1">SQLite does not start <a class="header-anchor" href="#sqlite-does-not-start" aria-label="Permalink to &quot;SQLite does not start&quot;">​</a></h2><p>Keep the database, <code>-wal</code>, and <code>-shm</code> files together on local storage. Check UID/GID 1000 ownership, free disk space, integrity, and migration compatibility. Network filesystems and horizontal replicas are unsupported.</p>',13)])])}const f=t(i,[["render",s]]);export{p as __pageData,f as default};
